import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Версии и совместимость","description":"","frontmatter":{"pageId":"compatibility","contentRevision":5},"headers":[],"relativePath":"ru/compatibility.md","filePath":"ru/compatibility.md"}'),r={name:"ru/compatibility.md"};function o(n,a,s,d,h,p){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="версии-и-совместимость" tabindex="-1">Версии и совместимость <a class="header-anchor" href="#версии-и-совместимость" aria-label="Permalink to &quot;Версии и совместимость&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Нужны RimWorld 1.7, Rimlink 0.9.2 и Harmony 3.x. Сервер и мод должны быть совместимых версий; номер сетевого протокола сейчас 1. Используй пакет релиза и набор модов, опубликованный администратором.</p><p>Порядок модов, packageId, версии, содержимое файлов и серверные настройки набора могут проверяться при подключении. Окно различий объясняет, что заменить. Перед обновлением сохрани локальную резервную копию и закрой игру.</p><h2 id="checklist" tabindex="-1">Как сверить сборку до подключения? <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Как сверить сборку до подключения? {#checklist}&quot;">​</a></h2><p>Сверь четыре независимых слоя: RimWorld 1.7; Rimlink 0.9.2 на клиенте и сервере; Harmony 3.x; коллекцию конкретного сервера. Совпадение названия мода недостаточно: packageId, версия, порядок, содержимое файлов и общие настройки могут отличаться.</p><ol><li>Получи версию Rimlink и список обязательных DLC у администратора.</li><li>Убери вторую копию того же packageId из активного списка: Workshop и локальная папка не должны спорить за один мод.</li><li>Дай игре перезапуститься после изменения сборки. Загруженные DLL не заменяются надёжно на лету.</li><li>Пройди диалог сверки. Для визита или live дополнительно должна загрузиться карта хозяина с её зависимостями.</li></ol><p>«Новая версия» не всегда означает совместимость со старым сервером. Если Workshop уже обновился, а сервер требует старые файлы, нужен согласованный администратором пакет или обновление сервера, не правка hash вручную.</p><h2 id="verified" tabindex="-1">Что проверено, а что нельзя обещать? <a class="header-anchor" href="#verified" aria-label="Permalink to &quot;Что проверено, а что нельзя обещать? {#verified}&quot;">​</a></h2><p>Наличие автоматических тестов серверной логики не доказывает совместимость каждого игрового мода. Изменяющие сериализацию, пешек, работу карты или UI модификации требуют отдельной проверки вашей сборки. Перед массовым переходом проверь вход, загрузку колонии, передачу предмета и нужный live-сценарий на тестовом сервере.</p><p>Серверная доставка без Steam проверялась на изолированной копии Steam-установки. Это не приёмка настоящего GOG runtime. Для GOG понадобится разрешённый парольный вход и законно распространяемые зависимости; Core/DLC по сети не передаются.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Steam-проверка требует запущенного Steam. Для GOG нужен разрешённый парольный вход и распространяемый сервером пакет; полноценный запуск именно GOG пока не подтверждён. Core и DLC не распространяются через Rimlink.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./players/install">Установка мода</a></li><li><a href="./players/modpacks">Набор модов сервера</a></li><li><a href="./admins/updating">Обновление сервера и клиентов</a></li></ul>',16)])])}const u=e(r,[["render",o]]);export{m as __pageData,u as default};
